import { useEffect, useState } from 'react';

const Dashboard = () => {
  const [metrics, setMetrics] = useState<React.ReactNode>(null);
  useEffect(() => {
    // 嵌套链第三层：Dashboard -> Metrics
    import('./Metrics').then((m) => setMetrics(m.default()));
  }, []);
  return (
    <div>
      <h2>dashboard</h2>
      {metrics}
    </div>
  );
};
export default Dashboard;
